<?php
require __DIR__.'/includes/session.php'; require __DIR__.'/includes/admin-layout.php'; require __DIR__.'/includes/admin-data.php';
$account=require_account(true); $runs=[]; $error='';
try { $db=spellstorm_database(); if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $id=field('id'); if(!preg_match('/\A[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\z/i',$id)) throw new InvalidArgumentException('Invalid run.'); $stmt=$db->prepare('DELETE FROM public.game_runs WHERE id=?'); $stmt->execute([$id]); redirect_to('admin-leaderboard.php?saved=1'); } $runs=admin_runs($db,true); } catch(Throwable $e) { $error='Unable to load or manage results.'; }
admin_header('Leaderboard Management','leaderboards',$account); ?>
<p>Review the highest recorded game scores and remove invalid results.</p><?php if($error): ?><p class="error"><?=escape($error)?></p><?php elseif(isset($_GET['saved'])): ?><p role="status">Result removed.</p><?php endif; ?>
<section class="admin-panel"><?php if(!$runs): ?><p class="empty">No game results recorded yet.</p><?php else: ?><div class="table-responsive"><table class="table table-dark"><thead><tr><th>Player</th><th>Score</th><th>Circle</th><th>Grimoire</th><th>Result</th><th>Action</th></tr></thead><tbody><?php foreach($runs as $run): ?><tr><?php foreach(['username','score','highest_circle','grimoire','result'] as $key): ?><td><?=escape((string)$run[$key])?></td><?php endforeach; ?><td><form method="post" onsubmit="return confirm('Remove this game result permanently?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=escape($run['id'])?>"><button class="btn btn-outline-danger btn-sm">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php admin_footer(); ?>
